<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {ApiError,currentUser,request,type Profile,pretty} from './api';
const props=defineProps<{id:string}>();const emit=defineEmits(['saved']);
const profile=ref<Profile|null>(null),revision=ref(0),catalog=ref<{characters:string[];accessories:string[]}>({characters:[],accessories:[]}),reason=ref(''),error=ref(''),busy=ref(false),conflict=ref(false),latest=ref<any>(null),pending=ref<any>(null);
const canEdit=computed(()=>currentUser.value?.role!=='VIEWER');
async function load(){busy.value=true;error.value='';try{const [p,c]=await Promise.all([request('/profiles/'+props.id),request('/catalog')]);profile.value=p.profile;revision.value=p.revision;catalog.value=c;conflict.value=false;latest.value=null;pending.value=null;reason.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
async function save(retry=false){if(!profile.value||!canEdit.value||busy.value||conflict.value)return;error.value='';if(!retry){if(!reason.value.trim()){error.value='변경 이유를 입력하세요.';return;}if(profile.value.first_granted&&!profile.value.characters.includes(profile.value.selected_character)){error.value='선택 캐릭터를 보유 목록에서 선택하세요. 회수할 때 대체 선택이 필요합니다.';return;}if(profile.value.selected_accessory&&!profile.value.accessories.includes(profile.value.selected_accessory)){error.value='선택 장신구를 보유 목록에서 선택하거나 없음으로 변경하세요.';return;}pending.value={request_id:crypto.randomUUID(),expected_revision:revision.value,reason:reason.value.trim(),profile:structuredClone(JSON.parse(JSON.stringify(profile.value)))};}busy.value=true;try{const result=await request('/profiles/'+props.id,'PUT',pending.value);profile.value=result.profile;revision.value=result.revision;reason.value='';pending.value=null;emit('saved');}catch(e){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===409){conflict.value=true;pending.value=null;latest.value=await request('/profiles/'+props.id).catch(()=>null);}else if(e instanceof ApiError&&e.status<500)pending.value=null;}finally{busy.value=false;}}
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert title="관리자 변경은 다음 프로필 조회에 반영됩니다. 실행 중인 게임은 재접속 또는 프로필 재조회가 필요합니다." type="info" :closable="false"/><el-alert v-if="!canEdit" title="조회자 권한: 프로필을 수정할 수 없습니다." type="info" :closable="false"/><el-alert v-if="conflict" title="변경 번호가 다르거나 요청이 충돌했습니다. 최신 데이터를 확인한 뒤 다시 편집하세요." type="warning" :closable="false"/><template v-if="conflict"><h3>최신 저장 데이터</h3><pre>{{pretty(latest)}}</pre><el-button @click="load">최신 데이터로 다시 열기</el-button></template><el-form v-if="profile" class="profile-form" label-position="top" :disabled="!canEdit||busy||conflict||!!pending"><p>변경 번호 {{revision}} · 첫 지급 {{profile.first_granted?'완료':'미완료 (유지)'}}</p><el-form-item label="닉네임"><el-input v-model="profile.nickname" aria-label="닉네임" maxlength="12"/></el-form-item><el-form-item label="보유 캐릭터"><el-select v-model="profile.characters" multiple aria-label="보유 캐릭터" :disabled="!profile.first_granted"><el-option v-for="id in catalog.characters" :key="id" :value="id" :label="id"/></el-select></el-form-item><el-form-item label="선택 캐릭터"><el-select v-model="profile.selected_character" aria-label="선택 캐릭터"><el-option v-if="!profile.first_granted" value="" label="없음"/><el-option v-for="id in profile.characters" :key="id" :value="id" :label="id"/></el-select></el-form-item><el-form-item label="보유 장신구"><el-select v-model="profile.accessories" multiple aria-label="보유 장신구" :disabled="!profile.first_granted"><el-option v-for="id in catalog.accessories" :key="id" :value="id" :label="id"/></el-select></el-form-item><el-form-item label="선택 장신구"><el-select v-model="profile.selected_accessory" aria-label="선택 장신구"><el-option value="" label="없음"/><el-option v-for="id in profile.accessories" :key="id" :value="id" :label="id"/></el-select></el-form-item><el-form-item label="상대 캐릭터"><el-select v-model="profile.opponent_character" aria-label="상대 캐릭터"><el-option v-for="id in catalog.characters" :key="id" :value="id" :label="id"/></el-select></el-form-item><h3>접근성</h3><el-form-item label="글자 배율"><el-select v-model="profile.accessibility.text_scale" aria-label="글자 배율"><el-option v-for="n in [1,1.15,1.3]" :key="n" :value="n" :label="String(n)"/></el-select></el-form-item><el-checkbox v-model="profile.accessibility.reduce_visual_effects">시각 효과 줄이기</el-checkbox><el-checkbox v-model="profile.accessibility.haptics_enabled">진동 사용</el-checkbox><h3>미니맵</h3><el-form-item label="투명도 (0~90)"><el-input-number v-model="profile.minimap.transparency" :min="0" :max="90" :step="1"/></el-form-item><el-form-item label="표시 모양"><el-select v-model="profile.minimap.marker_style"><el-option value="face" label="얼굴"/><el-option value="dot" label="점"/></el-select></el-form-item><el-checkbox v-model="profile.minimap.show_names">이름 표시</el-checkbox><el-form-item label="변경 이유"><el-input v-model="reason" aria-label="변경 이유" type="textarea" maxlength="1000"/></el-form-item><el-button v-if="canEdit" type="primary" :disabled="busy||conflict||!!pending" @click="save()">프로필 저장</el-button></el-form><div v-if="pending" class="toolbar"><el-alert title="저장 결과를 확인하지 못했습니다. 같은 요청을 다시 보내 결과를 확인하세요." type="warning" :closable="false"/><el-button :loading="busy" @click="save(true)">같은 요청 재시도</el-button></div></template>
